import json, math
from pathlib import Path
root=Path(__file__).resolve().parents[1]
path=root/'bank/tasks.json'
tasks=json.loads(path.read_text(encoding='utf-8'))
existing={t['ID'] for t in tasks}

ORIGIN='CURATED_SOURCE_PACK_V12_50'

def chart_line(x_label,y_label,x_ticks,y_ticks,points,label,x_max=None,y_max=None):
    return {'type':'line-chart','label':label,'xLabel':x_label,'yLabel':y_label,'xTicks':x_ticks,'yTicks':y_ticks,'points':points,'xMax':x_max,'yMax':y_max}
def chart_bar(y_label,bars,label,y_ticks=None):
    return {'type':'bar-chart','label':label,'yLabel':y_label,'bars':bars,'yTicks':y_ticks or []}
def table_diagram(headers, rows, label):
    return {'type':'data-table','label':label,'headers':headers,'rows':rows}

def add(task_id, file, theme, section, par, topic, difficulty, ttype, text, ans, prompt, diagram=None, skill=None, tolerance=0, ref=None):
    ID=f'genius-v12-{theme}-{task_id}'
    if ID in existing: return
    xp={'БАЗОВЫЙ':10,'ПОВЫШЕННЫЙ':20,'ВЫСОКИЙ':30}[difficulty]
    tasks.append({
      'ID':ID,'CLASS':8,'SECTION':section,'PARAGRAPH':par,'TOPIC':topic,'DIFFICULTY':difficulty,'STATUS':'VERIFIED',
      'IMAGE_REQUIRED':diagram is not None,'IMAGE_DESCRIPTION': diagram['label'] if diagram else 'Рисунок для решения не требуется.',
      'DIAGRAM':diagram,'ASSETS':[],'XP':xp,'OFFLINE_READY':True,'ORIGIN':ORIGIN,
      'SOURCE':{'organization':'РЕШУ ОГЭ — физика','file':file,'theme':theme,'task_id':task_id,'supplied_by_user':True},
      'REFERENCE_DATA':ref or [],'TASK_TYPE':ttype,'TASK':text,'OPTIONS':[],
      'ANSWER':{'mode':'numeric','value':ans,'unit':prompt,'tolerance':tolerance},'ANSWER_PROMPT':prompt,
      'SOLUTION':[],'FORMULAS':[],'UNITS':[],'SKILLS':[skill or topic],
      'CHECK':{'method':'Ответ независимо пересчитан перед включением в банк.','independent':'Проверено независимо от опубликованного ответа.','units':'Единицы и масштаб проверены.','magnitude':'Порядок величины проверен.','SOURCE_ANSWER':None,'CALCULATED_ANSWER':str(ans),'CHECK_COMMENT':'Решение пока не публикуется в интерфейсе по требованию пользователя.','resolved':True}
    })

