add(53,f98,'98','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Гиря падает на землю и ударяется абсолютно неупруго о препятствие. Скорость гири перед ударом равна 14 м/с. Температура гири перед ударом составляла 20 °C. До какой температуры нагреется гиря, если считать, что все количество теплоты, выделяемое при ударе, поглощается гирей? Удельная теплоемкость вещества, из которого изготовлена гиря, равна 140 Дж/(кг·°С).',20.7,'Введите конечную температуру, °C',tolerance=0.05)
add(161,f98,'98','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Металлический шар массой m₁ = 2 кг упал на свинцовую пластину массой m₂ = 1 кг и остановился. При этом пластина нагрелась на 3,2 °C. С какой высоты упал шар, если на нагревание пластины пошло 80% выделившегося при ударе количества теплоты? (Удельная теплоемкость свинца — 130 Дж/(кг · °С).)',26,'Введите высоту, м')
add(188,f98,'98','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Металлический шар массой m₁ = 2 кг упал с высоты h = 26 м на свинцовую пластину массой m₂ = 1 кг и остановился. На сколько градусов нагрелась пластина, если на ее нагревание пошло 80% выделившегося при ударе количества теплоты? (Удельная теплоемкость свинца — 130 Дж/(кг · °С).)',3.2,'Введите изменение температуры, °C',tolerance=0.05)
add(350,f98,'98','thermal',14,'Работа сил сопротивления и нагревание','ВЫСОКИЙ','calculation','Стальной осколок, падая с высоты 470 м, нагрелся на 0,5 °C в результате совершения работы сил сопротивления воздуха. Чему равна скорость осколка у поверхности земли? (Удельная теплоемкость стали — 460 Дж/(кг·°С).)',94.55,'Введите скорость, м/с',tolerance=0.6)
add(940,f98,'98','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Ударная часть молота массой 10 т свободно падает с высоты 2,5 м на стальную деталь массой 200 кг. Сколько ударов сделал молот, если деталь нагрелась на 20 °C? На нагревание детали расходуется 25% механической энергии молота.',32,'Введите число ударов')
add(944,f98,'98','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Ударная часть молота массой 10 т свободно падает с высоты 2,5 м на стальную деталь. Какую массу имеет стальная деталь, если после 32 ударов она нагрелась на 20 °C? На нагревание расходуется 25% энергии молота.',200,'Введите массу детали, кг')
add(23882,f98,'98','thermal',14,'Превращение механической энергии во внутреннюю','ВЫСОКИЙ','calculation','Чему paвна температура воды у основания водопада, если у его вершины она равнялась 20 °C? Высота водопада составляет 100 м. Считать, что 84% энергии падающей воды идет на ее нагревание.',20.2,'Введите температуру, °C',tolerance=0.05)
add(25106,f98,'98','thermal',26,'КПД двигателя','ВЫСОКИЙ','calculation','Каков КПД двигателя автомобиля, если при средней скорости 70 км/ч он потребляет 20 кг бензина на 140 км пути? Полезная мощность двигателя автомобиля составляет 46 кВт.',36,'Введите КПД, %',tolerance=0.2)
add(25367,f98,'98','thermal',26,'КПД двигателя','ВЫСОКИЙ','calculation','КПД двигателя трактора равен 25%. Какую максимальную полезную работу он может совершить, израсходовав 10 кг бензина?',115,'Введите работу, МДж',tolerance=0.2)
add(31530,f98,'98','thermal',17,'Тепловой баланс со льдом','ВЫСОКИЙ','calculation','В калориметр поместили 200 г мокрого снега и долили 200 г воды при температуре 100 °C. После этого снег растаял, и в калориметре установилась температура 20 °C. Сколько замерзшей воды содержал мокрый снег первоначально?',152.7,'Введите массу замёрзшей воды, г',tolerance=0.5)

f101='phys-oge.sdamgia.ru_test_theme=101&print=true.pdf'
# 10 type 22 high-level tasks
add(1163,f101,'101','thermal',17,'Плавление и нагревание','ВЫСОКИЙ','calculation','Имеются две порции воды одинаковой массы, находящиеся при температуре 0 °C. Первую порцию нагревают, затрачивая при этом количество теплоты Q₁. Если заморозить вторую порцию, чтобы она полностью превратилась в лед, то она выделит в 2,7 раза большее количество теплоты. Определите, на сколько градусов Δt нагревается первая порция воды при сообщении ей количества теплоты Q₁.',29.1,'Введите Δt, °C',tolerance=0.2)
add(1190,f101,'101','thermal',17,'Плавление и нагревание','ВЫСОКИЙ','calculation','Имеются две порции воды одинаковой массы, находящиеся при температуре 0 °C. Первую порцию нагревают на 17 °C, затрачивая при этом количество теплоты Q₁. Во сколько раз n большее количество теплоты выделяется при полном превращении в лед второй порции воды?',4.62,'Введите n',tolerance=0.03)
add(1271,f101,'101','thermal',12,'Тепловой баланс смесей','ВЫСОКИЙ','calculation','В калориметре смешивают две жидкости. Объем второй жидкости в 1,2 раза больше объема первой; плотность первой жидкости в 1,6 раза больше плотности второй; удельная теплоемкость первой жидкости в 2 раза меньше, чем удельная теплоемкость второй, а температура первой жидкости, равная 20 °C, в 2 раза больше, чем температура второй. Определите установившуюся температуру смеси. Потерями теплоты можно пренебречь.',14,'Введите температуру смеси, °C')
add(1298,f101,'101','thermal',12,'Тепловой баланс смесей','ВЫСОКИЙ','calculation','В калориметре смешивают две жидкости. Объем первой жидкости в полтора раза меньше объема второй; плотность второй жидкости в 1,25 раза меньше плотности первой; удельная теплоемкость второй жидкости составляет 2/3 удельной теплоемкости первой, а температура первой жидкости, равная 25 °C, в 2,8 раза меньше, чем температура второй. Определите установившуюся температуру смеси. Потерями теплоты можно пренебречь.',45,'Введите температуру смеси, °C')
add(3328,f101,'101','thermal',17,'Плавление свинца при постоянной мощности','ВЫСОКИЙ','calculation','Кусок свинца, имеющего температуру 27 °C, начинают нагревать на плитке постоянной мощности. Через 10 минут от начала нагревания свинец нагрелся до температуры плавления. Сколько еще времени потребуется для плавления свинца?',6.41,'Введите время, мин',tolerance=0.1)
add(25298,f101,'101','thermal',11,'Нагревание воды с учётом КПД','ВЫСОКИЙ','calculation','Воду массой 2 кг нагрели до температуры кипения за 7 мин. Мощность электронагревателя равна 2 кВт, КПД нагревателя − 80%. Какой была начальная температура воды?',20,'Введите начальную температуру, °C')
add(25327,f101,'101','thermal',17,'Плавление снега','ВЫСОКИЙ','calculation','В снежный сугроб, имеющий температуру 0 °C, бросили раскаленный до температуры 600 °C стальной шар массой 2,2 кг. Какова масса расплавленного снега? Потерями энергии в окружающую среду и испарением воды пренебречь.',2,'Введите массу расплавленного снега, кг',tolerance=0.05)
add(25385,f101,'101','thermal',17,'Нагревание и плавление олова','ВЫСОКИЙ','calculation','В стальной коробке массой 500 г находится олово массой 300 г при температуре 32 °C. Какое количество теплоты потребуется, чтобы расплавить олово? Потерями энергии в окружающую среду пренебречь. Температура плавления стали значительно больше температуры плавления олова.',81.5,'Введите количество теплоты, кДж',tolerance=0.5)
add(29636,f101,'101','thermal',14,'Механическая энергия и нагревание','ВЫСОКИЙ','calculation','Стальной молот падает с высоты 10 м и забивает сваю. При ударе 50% энергии идет на его нагревание. На сколько градусов нагревается молот? Удар считать абсолютно неупругим.',0.1,'Введите изменение температуры, °C',tolerance=0.01)
add(32475,f101,'101','thermal',12,'КПД электрического чайника','ВЫСОКИЙ','calculation','Воду массой 2 кг, имеющую начальную температуру 25 °С, нагрели в электрическом чайнике до температуры кипения за 6 мин. Мощность электрического чайника равна 2 кВт. Чему равен КПД чайника?',87.5,'Введите КПД, %',tolerance=0.2)

